import{_ as n,C as a,c as s,o,aj as l,G as t,w as c}from"./chunks/framework.Bfdr4H5E.js";const h="/sk/images/TradingView-Watchlist1.webp",d="/sk/images/TradingView-Watchlist2.webp",g="/sk/images/TradingView-Watchlist3.webp",p="/sk/images/TradingView-Details1.webp",m="/sk/images/TradingView-Details3.webp",u="/sk/images/TradingView-Hotlists.webp",w="/sk/images/TradingView-Calendar.webp",f="/sk/images/TradingView-Order-Panel.webp",b="/sk/images/TradingView-DOM.webp",D=JSON.parse('{"title":"TradingView – Right Bar","description":"","frontmatter":{"outline":"deep","prev":{"text":"TradingView – Favorite Tools and Tricks","link":"/trading-with-pav/tradingview-favorite-tools-and-tricks"},"next":{"text":"Trading Position","link":"/trading-with-pav/trading-position"}},"headers":[],"relativePath":"trading-with-pav/tradingview-right-bar.md","filePath":"trading-with-pav/tradingview-right-bar.md"}'),y={name:"trading-with-pav/tradingview-right-bar.md"};function k(_,e,T,v,C,V){const r=a("GraphComment"),i=a("ClientOnly");return o(),s("div",null,[e[0]||(e[0]=l('<h1 id="tradingview-–-right-bar" tabindex="-1">TradingView – Right Bar <a class="header-anchor" href="#tradingview-–-right-bar" aria-label="Permalink to &quot;TradingView – Right Bar&quot;">​</a></h1><p>In this article we goanna take a look at TradingView – Right Bar which has Watchlist and details, Alerts, Hotlists, Calendar, Order Panel and DOM</p><div class="info custom-block"><p class="custom-block-title">Table of Contents</p><nav class="table-of-contents"><ul><li><a href="#watchlist-details-and-news">Watchlist Details and News</a></li><li><a href="#alerts">Alerts</a></li><li><a href="#hotlists">Hotlists</a></li><li><a href="#calendar">Calendar</a><ul><li><a href="#economic-calendar">Economic Calendar</a></li><li><a href="#earnings-calendar">Earnings Calendar</a></li></ul></li><li><a href="#order-panel">Order Panel</a></li><li><a href="#depth-of-market-dom">Depth of Market (DOM)</a></li><li><a href="#comments">Comments</a></li></ul></nav></div><h2 id="watchlist-details-and-news" tabindex="-1">Watchlist Details and News <a class="header-anchor" href="#watchlist-details-and-news" aria-label="Permalink to &quot;Watchlist Details and News&quot;">​</a></h2><p>In watchlist you can store any scripts instead of always opening through search function. For Free account you have only one watchlist and Red List (Basically a watchlist but defined through color).</p><p>For paid subscription you get unlimited watchlist and unlocks all 7 color watchlist Red, Blue, Green, Orange, Purple, Aqua, Pink. As you can see below 2nd image Free account has 1 watchlist and 1 color list.</p><p><img src="'+h+'" alt="TradingView-Watchlist1"></p><p><img src="'+d+'" alt="TradingView-Watchlist2"></p><p>In the above 1st image left you can see you the list has INDICES, STOCKS, FUTURES etc. those are called section in “<strong>watchlist</strong>“. This helps use to categorize our scripts according to needs like Sectors, Forex list etc. You can even customize the columns as seen in the image below.</p><p><img src="'+g+'" alt="TradingView-Watchlist3"></p><p><img src="'+p+'" alt="TradingView-Details1"></p><p>In the above image you can see what the “<strong>details</strong>” are about the script active on chart which in this case its SBIN i.e. State Bank of India. On that image you can also see in top right corner is number 3 which in turn tells us its Earnings day for SBI.</p><p><img src="'+m+'" alt="TradingView-Details3"></p><p>As you can see in the left image in the menu you can select whatever details you want in the “<strong>details</strong>” panel. We use mostly listed in the image. You can select whatever you want the information is only crucial for Long term Investment.</p><h2 id="alerts" tabindex="-1">Alerts <a class="header-anchor" href="#alerts" aria-label="Permalink to &quot;Alerts&quot;">​</a></h2><p>The next on the right sidebar is Alerts. For free account you get to place 2 Alerts but there’s a catch 1 Alert for Price Alerts &amp; 1 for Technicals Alerts. But for regular user its enough. If you want to upgrade then SIGN UP from our link &amp; get 15$ credit <a href="https://www.tradingview.com/gopro/?share_your_love=YSTC" title="Open free TradingView Account" target="_blank" rel="noreferrer">click here</a>.</p><p>After Alerts there is Data Window which shows current charts data stream. Not that important to us. After that is Hotlists.</p><p><img src="'+u+'" alt="TradingView-Hotlists"></p><p><img src="'+w+'" alt="TradingView-Calendar"></p><h2 id="hotlists" tabindex="-1"><strong>Hotlists</strong> <a class="header-anchor" href="#hotlists" aria-label="Permalink to &quot;**Hotlists**&quot;">​</a></h2><p>As you can see in the above 2 images the 1st one is “<strong>Hotlists</strong>” you get 3 Section and get to select any market form the world for e.g. in the above image you can see we selected INDIA NSE 1st one is “<strong>Volume Gainers</strong>” 2nd we selected “<strong>% change Gainers</strong>” and 3rd one “<strong>% change Losers</strong>” you can use others from the list as well. This hotlists is basically like a readymade stock screener.</p><h2 id="calendar" tabindex="-1">Calendar <a class="header-anchor" href="#calendar" aria-label="Permalink to &quot;Calendar&quot;">​</a></h2><h3 id="economic-calendar" tabindex="-1">Economic Calendar <a class="header-anchor" href="#economic-calendar" aria-label="Permalink to &quot;Economic Calendar&quot;">​</a></h3><p>In the above 2nd image you can see the calendar which is split in 2 section. 1st section is “<strong>Economic Calendar</strong>“. Whichever market you trade select that country also country’s influencing you scripts. Economic Calendar has data points that describe the state of the country’s economy as a whole (GDP, Inflation Rate), the state of a particular industry (Steel Production), or a system (ICU Beds).</p><p>At the moment, 300 metrics are available for 200 countries. A complete list of available data can be found <a href="https://www.tradingview.com/support/folders/43000581956-list-of-available-economic-indicators/" target="_blank" rel="noreferrer">here</a>.</p><h3 id="earnings-calendar" tabindex="-1">Earnings Calendar <a class="header-anchor" href="#earnings-calendar" aria-label="Permalink to &quot;Earnings Calendar&quot;">​</a></h3><p>2nd section is “Earnings Calendar”. This section lists out all the instruments in the country selected are listed according to the Earnings. If you need more info on how to use Earnings you can read more about this <a href="https://www.tradingview.com/chart/?solution=43000629790" target="_blank" rel="noreferrer">here</a>.</p><p><img src="'+f+'" alt="TradingView-Order-Panel"></p><p><img src="'+b+'" alt="TradingView-DOM"></p><h2 id="order-panel" tabindex="-1">Order Panel <a class="header-anchor" href="#order-panel" aria-label="Permalink to &quot;Order Panel&quot;">​</a></h2><p>In the above left image you can see TradingView “<strong>Order Panel</strong>” connected to “<strong>Paper Trading</strong>“. You can practice on TradingView before starting the journey with real money. You can also connect <a href="https://invite.dhan.co/?invite=KJXFR31859" target="_blank" rel="noreferrer">Dhan</a> the only Indian Broker offering direct connection to trading panel.</p><h2 id="depth-of-market-dom" tabindex="-1">Depth of Market (DOM) <a class="header-anchor" href="#depth-of-market-dom" aria-label="Permalink to &quot;Depth of Market (DOM)&quot;">​</a></h2><p>Depth of Market DOM, aka the Order Book, is a window that shows how many open buy and sell orders there are at different prices for a security. Let’s say the current price is $1, the DOM will show how many orders there are at $0.90, $1.10, etc. It’s a great tool to see where the supply and demand levels are.</p><p>That’s it for this article hope all these TradingView articles make you learning journey smooth and helps you focus on analysis instead being stuck at knowing the basics of Charting platform.</p><h2 id="comments" tabindex="-1">Comments <a class="header-anchor" href="#comments" aria-label="Permalink to &quot;Comments&quot;">​</a></h2>',35)),t(i,null,{default:c(()=>[t(r)]),_:1})])}const A=n(y,[["render",k]]);export{D as __pageData,A as default};
